#!/bin/bash
# usage: batch2.sh <file>  -> word<TAB>plural<TAB>singular  (tabs/newlines in word not supported)
run(){ o=$(/workspace/dataset/test12_executable --a "1,2,3,4" --b "$1" 2>&1); p=$(sed -n 2p <<<"$o"); s=$(sed -n 4p <<<"$o"); printf '%s\t%s\t%s\n' "$1" "$p" "$s"; }
export -f run
xargs -d '\n' -I{} -P 32 bash -c 'run "$@"' _ {} < "$1"
