#!/bin/bash
# usage: p.sh <word> [count]   -> prints the 5 result lines for a word with `count` items
w="$1"; n="${2:-4}"
a=""
for ((i=1;i<=n;i++)); do if [ -z "$a" ]; then a="i$i"; else a="$a,i$i"; fi; done
/workspace/dataset/test12_executable --a "$a" --b "$w" 2>&1

# usage: awk -f gencase.awk -v w=word   -> prints all 2^len(w) case variants
BEGIN{
  n=length(w); lo=tolower(w); up=toupper(w);
  total=1; for(i=0;i<n;i++) total*=2;
  for(m=0;m<total;m++){
    s=""; t=m;
    for(i=1;i<=n;i++){
      bit = int(t/2)*2 == t ? 0 : 1;   # low bit
      t=int(t/2);
      s = s (bit ? substr(up,i,1) : substr(lo,i,1));
    }
    print s;
  }
}
