#!/bin/bash
# usage: mkNc.sh N WORD  -> N items using N-1 commas (all items empty strings) -> compact
n="$1"; w="$2"
if [ "$n" -le 1 ]; then a=""; else a=$(head -c $((n-1)) /dev/zero | tr '\0' ','); fi
/workspace/dataset/test12_executable --a "$a" --b "$w" 2>&1

