# usage: awk -f gen.awk  (reads words on stdin, one per line, emits all 2^len case patterns)
function up(c){ return toupper(c) }
{
  w=$0; n=length(w);
  if(n>10) n=10;              # cap
  total=1; for(i=0;i<n;i++) total*=2;
  for(m=0;m<total;m++){
    out="";
    for(i=1;i<=length(w);i++){
      c=substr(w,i,1);
      if(i<=n && int(m/(2^(i-1)))%2==1) out=out toupper(c); else out=out tolower(c);
    }
    print out;
  }
}
