function strip(s){ gsub(/^[ \t\n]+/,"",s); gsub(/[ \t\n]+$/,"",s); return s }
FNR==NR{
  # pass 1: build lowercase map + verbatim set
  if($1 ~ /^[a-z]+$/) map[$1]=$2;
